#include <cuda.h>
#include <cuda_fp16.h>
#include <torch/extension.h>

// Tile size (must be multiples of warp size for good occupancy)
#define TILE_M 128
#define TILE_N 128
#define TILE_K 16   // matches WMMA tile K dimension

// Thread block dimensions
#define BLOCK_ROWS 8   // each thread computes 8 rows
#define BLOCK_COLS 8   // each thread computes 8 cols
// => 16 x 16 threads per block (256 threads)

extern "C" __global__
void matmul_fp16_kernel(const half* __restrict__ A,
                        const half* __restrict__ B,
                        half* __restrict__ C,
                        const int M,
                        const int N,
                        const int K) {
    // Block start indices
    const int block_row = blockIdx.y * TILE_M;
    const int block_col = blockIdx.x * TILE_N;

    // Thread indices within the block
    const int thread_row = threadIdx.y;   // 0..15
    const int thread_col = threadIdx.x;   // 0..15

    // Allocate shared memory for tiles of A and B
    __shared__ half As[TILE_M][TILE_K];
    __shared__ half Bs[TILE_K][TILE_N];

    // Each thread will compute a BLOCK_ROWS x BLOCK_COLS sub‑tile
    half acc[BLOCK_ROWS][BLOCK_COLS];
#pragma unroll
    for (int i = 0; i < BLOCK_ROWS; ++i)
#pragma unroll
        for (int j = 0; j < BLOCK_COLS; ++j)
            acc[i][j] = __float2half(0.0f);

    // Loop over K dimension tiles
    const int num_tiles_k = (K + TILE_K - 1) / TILE_K;
    for (int tk = 0; tk < num_tiles_k; ++tk) {
        // Load A tile into shared memory (cooperative)
        for (int i = 0; i < BLOCK_ROWS; ++i) {
            const int row = block_row + thread_row * BLOCK_ROWS + i;
            const int col = tk * TILE_K + thread_col;
            if (row < M && col < K) {
                As[thread_row * BLOCK_ROWS + i][thread_col] = A[row * K + col];
            } else {
                As[thread_row * BLOCK_ROWS + i][thread_col] = __float2half(0.0f);
            }
        }
        // Load B tile into shared memory (cooperative)
        for (int j = 0; j < BLOCK_COLS; ++j) {
            const int row = tk * TILE_K + thread_row;
            const int col = block_col + thread_col * BLOCK_COLS + j;
            if (row < K && col < N) {
                Bs[thread_row][thread_col * BLOCK_COLS + j] = B[row * N + col];
            } else {
                Bs[thread_row][thread_col * BLOCK_COLS + j] = __float2half(0.0f);
            }
        }
        __syncthreads();

        // Compute the sub‑tile
#pragma unroll
        for (int kk = 0; kk < TILE_K; ++kk) {
            half a_val[BLOCK_ROWS];
            half b_val[BLOCK_COLS];
#pragma unroll
            for (int i = 0; i < BLOCK_ROWS; ++i)
                a_val[i] = As[thread_row * BLOCK_ROWS + i][kk];
#pragma unroll
            for (int j = 0; j < BLOCK_COLS; ++j)
                b_val[j] = Bs[kk][thread_col * BLOCK_COLS + j];
#pragma unroll
            for (int i = 0; i < BLOCK_ROWS; ++i)
#pragma unroll
                for (int j = 0; j < BLOCK_COLS; ++j)
                    acc[i][j] = __hadd(acc[i][j], __hmul(a_val[i], b_val[j]));
        }
        __syncthreads();
    }

    // Write results back to global memory
    for (int i = 0; i < BLOCK_ROWS; ++i) {
        const int row = block_row + thread_row * BLOCK_ROWS + i;
        if (row < M) {
            for (int j = 0; j < BLOCK_COLS; ++j) {
                const int col = block_col + thread_col * BLOCK_COLS + j;
                if (col < N) {
                    C[row * N + col] = acc[i][j];
                }
            }
        }
    }
}
